    "en": "A figure of speech is language you do not mean literally. \"The soldier is a lion\" means he is brave. Three kinds: **tashbīh** (simile: both things are named), **isti'āra** (metaphor: one of the two things is hidden), **kināya** (a phrase that could be literally true but really points to a quality, like \"his hand is clean\" = he is honest).",
    "academic": "الصور البيانية أساليب يُعبَّر بها عن المعنى بطريق غير مباشر. فالتشبيه عقد مماثلة بين شيئين يشتركان في صفة. والاستعارة تشبيه حُذف أحد طرفيه. والكناية لفظ أُريد به لازم معناه مع جواز إرادة المعنى الأصلي.",
    "analogy": "تخيّل صورة فيها شخصان. في **التشبيه** يظهر الاثنان في الصورة. في **الاستعارة** يظهر واحد فقط، وتعرف الآخر من ظلّه. وفي **الكناية** لا تصوّر الشخص أبدًا، بل تصوّر أثره، كأن تصوّر بابًا مفتوحًا لتقول: صاحب البيت كريم."
