    "title": "مصباحُ الجدّة",
    "text": "كانتِ الليلةُ باردةً، والرياحُ تصرخُ خلفَ النوافذِ. جلسَ سالمٌ قربَ جدّتِه في البيتِ القديمِ، وفجأةً انقطعتِ الكهرباءُ، فصارَ البيتُ مظلمًا. خافَ سالمٌ، وقالَ بصوتٍ مرتجفٍ: يا جدّتي، متى يعودُ النورُ؟\n\nابتسمتِ الجدّةُ، وأشعلتْ مصباحًا قديمًا، وقالتْ: لا تخفْ يا صغيري. هذا المصباحُ رفيقي منذُ خمسينَ سنةً. اجلسْ بجانبي واسمعْ حكايتَه.\n\nحكتِ الجدّةُ كيفَ كانَ أبوها يحملُ المصباحَ كلَّ ليلةٍ ليدلَّ المسافرينَ على الطريقِ. كانَ قلبُه أبيضَ، وبابُه مفتوحًا للجميعِ. قالَ سالمٌ: ما أجملَ هذه الحكايةَ!\n\nنسيَ سالمٌ خوفَه، ونامَ قربَ المصباحِ. وفي الصباحِ عادتِ الكهرباءُ، لكنَّ سالمًا قالَ: الجدّةُ مصباحُ هذا البيتِ."
