    "title": "الصيّادُ والبحر",
    "text": "خرجَ الصيّادُ راشدٌ إلى البحرِ قبلَ الفجرِ، وكانَ البحرُ هادئًا كطفلٍ نائمٍ. رمى شبكتَه وانتظرَ طويلًا، لكنَّ الشبكةَ ظلّتْ فارغةً.\n\nوعندَ الظهرِ تغيّرَ كلُّ شيءٍ. غضبَ البحرُ، وصارتِ الأمواجُ جبالًا عاليةً. صاحَ راشدٌ: يا ربِّ، نجِّني! أمسكَ المجدافَ بيدينِ قويّتينِ، وقالَ لنفسِه: لا تستسلمْ، أولادُكَ ينتظرونَكَ.\n\nظلَّ راشدٌ يجدّفُ ساعاتٍ، والقاربُ الصغيرُ يرقصُ فوقَ الموجِ. ثمّ رأى ضوءًا بعيدًا. كانَ أهلُ القريةِ قد أشعلوا نارًا كبيرةً على الشاطئِ ليهتديَ بها.\n\nوصلَ راشدٌ إلى الشاطئِ متعبًا، صِفْرَ اليدينِ؛ فلم يكنْ في قاربِه سمكةٌ واحدةٌ. سألَه ابنُه: أينَ السمكُ يا أبي؟ ضحكَ وقالَ: عدتُ إليكم سالمًا، وهذا أعظمُ صيدٍ."
