      "title": "Partial sum of an arithmetic series",
      "content": "General (know a₁ and aₙ):   Sₙ = n(a₁ + aₙ)/2\nAlternate (know a₁ and d):   Sₙ = (n/2)[2a₁ + (n − 1)d]"
