      "answer": "(a) Sₙ = 8500, n = 10, d = 100.\n(b) Use Sₙ = (n/2)[2a₁ + (n − 1)d]: 8500 = (10/2)[2a₁ + 9(100)] → 8500 = 5(2a₁ + 900) → 1700 = 2a₁ + 900 → a₁ = AED 400.\n(c) a₁₀ = 400 + (10 − 1)(100) = AED 1300. (Check: 10(400 + 1300)/2 = 8500 ✓)",
